"""Low level interaction functions for Inhibits window and pane"""

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.xvi.interactions.objects.xvi_objects import Xvi_MainPage
from interops.libraries.miscellaneous.decorators import log_decorator,LogMeta
from interops.libraries.xvi.interactions.common_objects_ops import get_text,click_item

class ViewInhibitsOps(metaclass = LogMeta):
    '''
    Class to handle View Inhabits and operations
    '''
    def __init__(self) -> None:
        #squishtest.waitForObject(Xvi_MainPage.view_Inhibits_Dialog)
        self._inhibits = {}
        lst = squishtest.waitForObject(Xvi_MainPage.view_Inhibits_Inhibit_List)
        listItems = squishtest.object.children(lst)
        for l in listItems:
            if getattr(l, 'type', '') == 'ListItem':
                self._inhibits[l.index] = l.text

    @property
    def has_duplicate_names(self):
        vals = self._inhibits.values()
        return len(vals) != len(set(vals))

    @property
    def inhibits(self):
        return self._inhibits

    @property
    def inhibit(self):
        lst = squishtest.waitForObject(Xvi_MainPage.view_Inhibits_Inhibit_List)
        listItems = squishtest.object.children(lst)
        for l in listItems:
            if getattr(l, 'type', '') == 'ListItem' and l.selected:
                self._inhibit = (l.index, l.text)
                break
        return self._inhibit

    @inhibit.setter
    def inhibit(self, value):
        if not isinstance(value, tuple) or len(value) != 2:
            raise Exception("Value should be a pair (index, name).")
        if sum(1 for val in self._inhibits.values() if val == value) > 1:
            self._innitibt = (value[0], self.click_item_by_index(value[0]))
        else:
            click_item(Xvi_MainPage.view_Inhibits_Inhibit_List, value[1], True)
            self._innitibt = value

    @property
    def description(self):
        self._description = get_text(Xvi_MainPage.view_Inhibits_Description_Edit)
        return self._description

    @property
    def action(self):
        self._action = get_text(Xvi_MainPage.view_Inhibits_Action_Edit)
        return self._action

    def click_OK_button(self):
        return common.left_click_object(Xvi_MainPage.view_Inhibits_OK_Button)

    def click_item_by_index(self, index):
        lst = squishtest.waitForObject(Xvi_MainPage.view_Inhibits_Inhibit_List)
        listItems = squishtest.object.children(lst)
        for l in listItems:
            if getattr(l, 'type', '') == 'ListItem':
                if l.index == index:
                    common.left_click_object(l)
                    return l.text

@log_decorator
def get_inhibits_string():
    '''
    Get the inhbits string
    '''
    return get_text(Xvi_MainPage.xviAppInhibitDisplay_Inhibits_Status_Label)

@log_decorator
def get_generator_status():
    '''
    Get the generator's status
    '''
    return get_text(Xvi_MainPage.xviAppInhibitDisplay_Ready_Status_Label)
